#!/usr/bin/env python3
"""Full German per-passage gist for High Water (book 7). Draft, pending native review."""
import json, os
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "content", "gist", "high-water", "de.json")
G = {
1: "Es ist die nasseste Nacht seit Jahren. Der Fluss ist den ganzen Tag unter hartem Regen gestiegen. In der tief gelegenen Straße steht das Wasser schon an den Türschwellen. Dann stürzt die alte Nora Kettle auf der nassen Stufe und kommt nicht mehr hoch. Die Sandsackmauer entlang der Gasse ist nicht gebaut, und das Wasser steht schon über dem Bordstein. Den Fluss aus den Häusern zu halten, liegt jetzt an dir.",
2: "Du holst, was der Schuppen hergibt: einen Stapel Säcke, einen Spaten, eine kleine Pumpe, eine gute Lampe. Draußen fällt der Regen gerade herab, und der Fluss steigt weiter. Das Wasser läuft schon über die Gasse. Du musst entscheiden, was zu tun ist, und zwar schnell.",
3: "Du versuchst das Telefon. Endlich kommt Toms Stimme von der Werft durch. Keine Mannschaft kann vor dem Morgen ausrücken, sagt er — nicht bei so einem Fluss. Bau die Mauer entlang der Gasse, sagt er, und halte sie, so gut du kannst, bis das Wasser fällt.",
4: "Du erreichst Nora am Fuß der Stufe und machst sie warm und trocken. Aber der Fluss steigt weiter, und Schutz allein reicht nicht. Die Häuser brauchen die Mauer, gebaut und gehalten. Du brauchst Säcke, einen Plan und einen klaren Kopf, bevor du hinausgehst.",
5: "Du trittst in die Gasse hinaus. Die Nacht ist riesig und voller Regen, und das schwarze Wasser glänzt im Lampenschein. Der Fluss drückt auf die ganze tief gelegene Straße wie eine Hand. Dann, weit weg, am Rand des Wassers, bewegt sich ein kleines Licht, wo heute Nacht niemand sein sollte.",
6: "Du zwingst dich zum Nachdenken. Du könntest zuerst die Mauer bauen und dich um den Rest später kümmern. Oder zu Nora und den Nachbarn gehen. Oder die ganze Straße wecken, um Hände zu haben. Jede Wahl kostet Zeit, die du nicht hast — und draußen steigt der Fluss schon.",
8: "Die Kälte legt sich wie ein Gewicht auf deine Brust. Du denkst an die Häuser der tief gelegenen Straße: alles, was diese Menschen haben. Bleibt die Mauer noch lange ungebaut, ist der Fluss bei Tagesanbruch drinnen. Das ist keine Angst; das ist eine Tatsache. Niemand sonst kommt. Du bist es, heute Nacht, oder niemand.",
9: "Tom stößt das Werftlager auf und hebt die Lampe. Drinnen: Paletten mit Sandsäcken, eine Pumpe, Seilrollen, trockene Sackleinwand. »Nimm, was du brauchst«, sagt er. »Ich bleibe am Telefon und rufe, wen ich kann.« Er ist ein fester Mann, und eine solche Nacht zeigt es.",
10: "Du klopfst die Reihe entlang, und der alte Herr Hollis öffnet, bleich im Dunkeln. Kein Strom, die Lampe tot, die Hände zu zittrig, um einen Sack zu heben. »Ich kann es nicht abhalten«, sagt er. Vor dir liegt eine lange Nacht. Aber er ist hier, voller Angst, und dich bittet er.",
11: "Du gehst geradewegs in die Gasse und stapelst, was du kannst. Ein Sack, ein Spaten voll Sand, eine niedrige Linie, die hier und da steigt. Aber die Mauer ist dünn und niedrig. Ohne echte Säcke hält sie keine Stunde. Du kannst nicht ein wenig bauen und hoffen.",
12: "Du gehst von Tür zu Tür mit denselben Worten. Bring Sand. Hilf an der Mauer. Hilf mir, die Linie zu halten. Manche wenden sich ab und schließen. Aber ein paar ziehen den Mantel an und treten in den Regen. Heute Nacht reichen ein paar zum Anfang.",
13: "Du übernimmst die Säcke und die Pumpe selbst. Die Palette ist schwer, und jeder Sack zählt jetzt. Gut gestapelt, halten sie den Fluss die ganze Nacht; vergeudet, ist das Wasser vor Tagesanbruch durch die Türen. Also drückst du sie an dich und gehst hinaus in die Gasse.",
14: "Du nimmst nur eine Lampe und einen Spaten. Zum Sehen und zum Sandbewegen. Aber nicht die Mauer selbst. Und du hast keine echten Säcke beiseitegelegt. Du brauchst echte Säcke, und bald. Sonst säuft die Gasse ab und der Fluss gewinnt.",
15: "Der alte Jack Reed kennt diesen Fluss besser als jeder andere. »Bleib weg vom Wehrsteg«, sagt er. »Er sieht aus wie eine Abkürzung. Ist er nicht — es ist ein Ertrinken.« Er warnt dich auch vor dem Händler. »Pass auf die Säcke auf, halte die Mauer — das ist die ganze Arbeit heute Nacht.«",
16: "Du baust eine Sacklinie vor Herrn Hollis' Tür und setzt ihn mit einer Decke hin. Nach und nach hört das Zittern auf. »Gott segne dich«, sagt er und drückt deine Hand. Du versprichst, wieder nach ihm zu sehen. Dann gehst du zurück in den Regen und die wartende Gasse.",
17: "Die Mauer kommt zuerst. Der Rest kann einen Moment warten. Aber wie anfangen? Du könntest erst echte Säcke von der Werft holen. Oder geradewegs in die Gasse gehen.",
18: "Die Arbeit zehrt an dir. Die Beine brennen, die Brust keucht, der Regen kämpft bei jedem Schritt gegen dich. Du bist an deiner Grenze, und du weißt es. Fällst du hier, bleibt niemand, der die Mauer hält. Also geh langsam, geh vorsichtig.",
19: "Die Straße erwacht. Die Leute beginnen sich zu rühren. Ein Mann schiebt eine Schubkarre voll Sand heraus. Eine Frau zerrt eine Rolle Säcke hervor. Tür um Tür nimmt ein Plan Gestalt an. Du bist nicht mehr allein. Und das ändert alles.",
20: "Niemand rührt sich. Die Türen bleiben zu, die Gesichter wenden sich von den Fenstern ab. Sie haben Angst, und ängstliche Menschen verstummen. Du kannst sie nicht zwingen. Also gehst du allein weiter. So ist es härter. Aber der Fluss wartet nicht auf sie.",
21: "Die nahe Mauer hält. Jetzt die Häuser am Ende. Zwei Wege hinunter. Die lange Gasse herum ist sicher, aber langsam. Der Wehrsteg ist schnell, geradeaus. Aber bei so einem Hochwasser kann das Wasser töten.",
22: "Du nimmst Jack Reeds Worte zu Herzen. Pass auf die Säcke auf. Weg vom Wehrsteg. Trau dem Händler nicht. Und halte die Mauer über allem. Einfacher Rat, und gut. Bleibt nur, ihn zu befolgen.",
23: "Die gute Tat festigt dich. Jemandem zu helfen festigt seltsamerweise auch dich. Der Kopf klarer, die Hände sicherer. Eine harte Nacht steht noch bevor. Aber du fühlst dich ihr gewachsen.",
24: "Ein Mann steht in der Gasse, eine Lampe in der Faust: der Händler. Er hat Pumpen zu verkaufen und Arme zu leihen, und er lächelt zu leicht. »Die Straße ist heute Nacht nicht wirklich deine Sache, Freund«, sagt er. Du hast seinesgleichen schon gesehen.",
25: "Du führst eine kleine Schar zur Mauer. Zusammen fühlt ihr euch stärker. Sie tragen Sand, Säcke, die Pumpe. »Hier entlang!«, rufst du im Regen, und sie kommen. Das tut gut, in so einer harten Stunde.",
26: "Die Gasse ist schwarz und überschwemmt, der Regen fegt sie entlang, nirgends Schutz. Aber der Boden ist fest unter den Füßen, und sie führt, wohin du musst. Also gehst du weiter, Schritt um Schritt.",
27: "Der Wehrsteg würde den Weg halbieren, die Häuser am Ende gleich dahinter. Aber die Planken sind alt und glatt über einem schnellen, tiefen Mühlbach. Jack Reed sagte, du sollst wegbleiben — und er scherzte nicht.",
28: "Du setzt den Fuß auf die Planken, und sofort fühlt es sich falsch an. Der Mühlbach wartet darunter, schwarz, tief, schnell. Jeder Schritt ist jetzt ein Wagnis — und du bist darauf, allein. Kein Zurück, einmal begonnen.",
29: "Die Pumpe saugt nicht an. Sie hustet, fasst eine Sekunde und stirbt. Ein harter Verlust bei so einem Hochwasser. Du musst die Säcke von Hand füllen und stapeln. Oder zur Werft zurück für eine andere Pumpe.",
30: "Die Gasse läuft weiter entlang der Reihe, das Wasser Stunde um Stunde tiefer. Darunter ein dunkles Haus, der Fluss schon an der Tür. Voraus scheint der peitschende Regen dich zurückzudrängen. Und ein Wegweiser, halb umgestürzt im Hochwasser.",
31: "Ein alter Mann ist in der überschwemmten Gasse gestürzt und kommt nicht hoch. Die Kälte packt ihn schon. Hältst du an, verlierst du Zeit, die du nicht hast. Tust du es nicht, übersteht er die Stunde vielleicht nicht.",
32: "Eine Familie sitzt in einem überfluteten Haus fest — kein Strom, kein Licht, ein weinendes Kind. Das Wasser steigt an ihren Füßen. Die Eltern sehen dich an, müde, ohne Hoffnung. Du hast eine Lampe und einen Mantel. Nicht viel. Aber mehr als sie.",
33: "Du drängst durch das Schlimmste des Regens, jeder Schritt ein Kampf, das Wasser zerrt an deinen Beinen. Vor dir liegen Entscheidungen. Vielleicht der Händler. Dieses seltsame Licht am Rand des Wassers. Oder geradewegs zur Mauer.",
34: "Du hilfst dem alten Mann auf und wärmst ihn, so gut du kannst. Seine Augen füllen sich, und er drückt dir ein Seil in die Hände. »Nimm es«, sagt er, »für deine Mühe.« Eine Kleinigkeit — aber frei gegeben. Du nimmst es und gehst weiter.",
35: "Du kannst nicht bleiben — aber sie auch nicht zurücklassen. Also versprichst du, Hilfe zu schicken. »Haltet durch!«, rufst du. »Geht nach oben, bleibt zusammen — ich vergesse euch nicht.« Und du meinst es. Dann wendest du dich und gehst.",
36: "Die Straße baut zuerst ein gutes Stück Mauer — ein fester Sackwall quer über die schlimmste Lücke, der das Wasser zurückwirft. Man drängt sich, die Säcke von Hand zu Hand zu reichen. Es ist nicht die ganze Gasse. Aber es ist echt, es hält, und es ist ein Anfang.",
37: "Haus um Haus wird die ängstliche Straße zu einer arbeitenden. Jeder hat eine Aufgabe: einer füllt Säcke, einer trägt sie, einer wacht über das Wasser. Angst wird zu Tun. Und Tun schlägt Warten, jedes Mal.",
38: "Die lange Mühe nagt an deinem Willen. Eine kleine Stimme sagt: hör auf, geh rein, ruh dich aus — niemand würde es dir verübeln, es wäre so leicht. Aber du denkst an die Häuser, das Wasser an ihren Türen. Und du verjagst die Stimme. Noch nicht. Nicht, solange sie zu retten sind.",
39: "Du erreichst den alten Wegweiser, aber das Hochwasser hat ihn gespalten und halb umgestürzt. Kaum zu lesen. Ein Arm zeigt die Gasse entlang. Der andere zum Rand des Wassers. Welcher Weg? Du musst raten, und richtig raten.",
40: "Der Händler wendet dir sein breites, leichtes Lächeln zu. »Nasse Arbeit, das«, sagt er. »Ich habe Pumpen zu verkaufen und Arme zu leihen — und die Straße ist heute Nacht nicht wirklich deine Sache, Freund.« Die Lampe schwingt. Sein Lächeln erreicht nie die Augen.",
41: "Das Angebot ist ein Haken, und du spürst ihn fassen. Er lehnt sich vor. »Die Straße ist schon verloren«, sagt er leise. »Lass den Fluss sein Werk tun — und es gibt einen Anteil für dich.« Es ist grausam, das zu sagen. Und es soll auf deine Angst wirken.",
42: "Du kehrst ihm den Rücken und überlässt ihn seinem kalten Handel. Es tut gut, wegzugehen. Er ruft dir nach, aber du drehst dich nicht um. Seinesgleichen findet immer jemanden, am Ende. Aber nicht dich, nicht heute Nacht.",
43: "Du nimmst seine Pumpe und seinen Handel. Deine Hände schließen sich darum, und etwas in dir weiß es schon. Sein Lächeln wird breiter. »Klug«, sagt er. Aber es fühlt sich gar nicht klug an. Es fühlt sich an wie eine Tür, die leise zugeht.",
44: "Du fragst ihn geradeheraus: was will er wirklich, und warum soll die Straße untergehen? Er lächelt und sieht die Gasse hinab. »Häuser sind billig nach einem Hochwasser«, sagt er. »So eine Nacht ist eine Gefälligkeit — für einen Käufer wie mich.«",
45: "Du trägst seine Säcke zur Mauer. Aber beim Stapeln rinnt der Sand sofort heraus. Das Tuch ist rissig und faul — es hält nichts. Die Linie sackt durch, niedrig und nutzlos.",
46: "Du öffnest einen Sack, und das Herz sinkt dir. Das Tuch ist rissig, faul. Diese Säcke halten das Wasser nie. Du hast gutes Geld gezahlt, und sie sind wertlos. Der Zweifel in deinem Bauch hatte recht.",
47: "Du suchst ihn, aber der Transporter des Händlers ist schon weg. Er half dir nie. Er wartete auf das Hochwasser, die ruinierten Häuser, das billige Land danach. Man hat dich getäuscht, ganz einfach.",
48: "Er ist weg, die Gasse leer — nur noch der Regen, das Dunkel, und was du ihm für nichts gabst. Du hast eine harte Lektion gelernt. Und viel zu teuer bezahlt. Du gehst weiter mit weniger als zu Beginn.",
49: "Die verängstigten Leute drücken ihm ihr Geld in die Hände. Fäuste voll Münzen, Stimmen, die um eine Pumpe flehen. Er nimmt es langsam, mit demselben Lächeln. Er wählt, wem er hilft, nach dem, wer am meisten zahlt.",
50: "Weit draußen auf der Brücke scheinen die Häuser am Ende endlich näher — oder doch nicht? Du bist dir nicht mehr sicher. Das Dunkel täuscht, und deine müden Augen auch. Und du bist weit von beiden Ufern.",
51: "Die Planken, das Dunkel, der tiefe Mühlbach darunter — und eine Planke bricht unter deinem Fuß. Das ist der Moment. Hinab ins schnelle Wasser. Oder zurückwerfen vom Bruch, solange du noch kannst.",
52: "Du erreichst endlich die Häuser am Ende, durchnässt, zitternd, die Hände wund — aber hinüber. Irgendwie hast du es geschafft. Jetzt musst du entscheiden: weiter, erschöpft, oder dem begegnen, was du im Wasser verloren hast.",
53: "Du wirfst dich zurück vom Bruch, solange du kannst — die harte, richtige Wahl. Du kriechst das letzte Stück auf Händen und Knien und erreichst das Ufer, erschüttert und langsam. Die Nacht ist nicht verloren. Aber sie kostete dich Zeit, die fehlen wird.",
54: "Du baust eine niedrige Sacklinie an ihrer Tür und schöpfst das Schlimmste des Wassers mit einem Eimer aus. Es hält den Fluss ein wenig ab. Aber es gibt keine Lampe zu lassen, und die Nacht ist lange nicht vorbei.",
55: "Du gibst ihnen deinen Mantel und deine Lampe, und die Familie drängt sich oben um die kleine Flamme, Erleichterung in den Gesichtern. Das Kind hört endlich auf zu weinen. »Danke«, sagt die Mutter — und dann zeigt sie dir ein Licht, am Rand des Wassers.",
56: "Ohne Mantel finden Kälte und Nässe dich schnell — die Zähne klappern, die Finger werden steif. Du gabst ihn weg, um zu helfen, und würdest es wieder tun. Aber dem Fluss ist das egal. Er steigt, nichts weiter.",
57: "Ein Fremder winkt dich in eine erleuchtete Tür. »Nur eine Minute«, sagen sie. »Raus aus dem Regen — schöpf Atem.« Es ist warm und trocken, und dein ganzer Körper fleht dich an zu bleiben. Aber so eine Minute gleitet schnell in eine Stunde.",
58: "Du drängst in den Regen, bis auf die Knochen durchkältet, der Wind kämpft bei jedem Schritt, die Augen brennen vom Wasser. Jeder Schritt ist eine kleine Schlacht. Aber du reihst sie aneinander, einen nach dem anderen, zu den Häusern.",
60: "Jemand zeigt zum Rand des Wassers: eine Gestalt ist dort hinausgegangen, allein, ins Dunkel. Draußen liegt nur das Hochwasser und der tiefe, schnelle Mühlbach. Geht niemand ihr nach, kommt sie vielleicht nicht zurück.",
61: "Du findest sie am Rand des Wassers, durchnässt und verloren, die Kälte zerrt an ihnen. Sie scheinen dein Gesicht nicht zu kennen. Du fasst sie fest am Arm. »Komm mit mir«, sagst du. »Jetzt ist es gut. Ich hab dich.«",
62: "Du kannst nicht alles tun, und die Mauer braucht dich am meisten. Also schickst du einen anderen hinterher und drängst weiter. Es lastet auf dir — aber heute Nacht musst du wählen, und wieder wählen.",
63: "Du bringst sie sicher zurück zu den Häusern, wo ihre Familie vor Erleichterung aufschreit. Man wickelt dich in einen trockenen Mantel und macht dir Platz am Feuer. »Danke«, sagen sie immer wieder. Aber die Gasse wartet, und du kannst nicht bleiben.",
64: "Du blickst über die ganze tief gelegene Straße — dunkel, steigend. Das Hochwasser glänzt schwarz zwischen den Häusern. Kein Licht irgendwo außer am Rand des Wassers. Die ganze Straße scheint den Atem anzuhalten und auf den Morgen zu warten.",
65: "Das Hochwasser steigt auf seinen Höhepunkt. Das Wasser erreicht seinen höchsten Stand, und dein Atem kommt kurz in der nassen Kälte. Schwer zu denken, zu rühren, dir überhaupt etwas daraus zu machen. Es ist die härteste Stunde der ganzen Nacht.",
67: "Tom drückt dir die letzte gute Lampe in die Hand. »Für die Gasse«, sagt er. »Geh — ich bleibe am Telefon.« Sein Gesicht grau vor Sorge. Das ist die Hilfe, die er heute Nacht geben kann, und er gibt sie von Herzen.",
68: "An der Werft stürzt man sich auf die Säcke — Stimmen steigen, Hände greifen, Angst breitet sich schnell aus. Ein Stoß mehr, und es wird eine Schlägerei. Du kannst versuchen, sie zu beruhigen und gerecht zu teilen. Oder deine nehmen und gehen.",
69: "Ein lange verschlossenes Haus umschließt dich — Feuchte, Stille, alte Kälte, ein Ort, wo nichts lebendig scheint. Dann hörst du es: ein Atem, schwach und nah, aus dem hinteren Zimmer. Jemand ist hier doch am Leben.",
70: "Weit draußen, am Rand des Wassers, hebt und senkt sich ein kleines Licht. Wo heute Nacht niemand sein sollte — es zeigt sich, verschwindet, zeigt sich wieder. Niemand kann es erklären. Und etwas in dir will hinausgehen und antworten.",
71: "Du erreichst den Rand des Wassers und rufst ins Dunkel. Nur der Regen antwortet. Dann siehst du es: eine kleine Gestalt, nahe dem Hochwasser, halb im dunklen Wasser. Jemand ist doch draußen. Und er bewegt sich kaum.",
72: "Du erreichst sie, und das Herz dreht sich dir um. Es ist ein Kind — Wren — zusammengerollt nahe dem Hochwasser, durchnässt, kaum wach. Die Kälte hat es. Keine Zeit zu warten. Du musst jetzt handeln.",
73: "Du rufst noch einmal ins Dunkel. Einen Moment nichts. Dann kommt eine dünne Stimme zurück, von der Kälte zerrissen: »Hier! Hier draußen!« Jemand ist draußen, am Wasser, und braucht Hilfe. Und er klingt gar nicht stark.",
74: "Du ziehst Wren aus dem Wasser und wickelst es in deinen Mantel. Langsam kommt es zu sich, klammert sich an deinen Arm. »Die Mauer«, flüstert es. »Halte die Mauer. Die Häuser ...« Selbst jetzt, durchnässt, denkt es an die Straße.",
75: "Du drehst dich um, um Hilfe zu holen — und hältst jäh inne. Keine Hilfe hier draußen, nicht vor dem Morgen. Keine Mannschaft, niemand. Du oder niemand, und Wren weiß es auch. Seine ängstlichen Augen folgen dir im Dunkel.",
76: "Wren blickt auf, die Augen klarer. »Die alte Dame, Nora — das ist meine Oma«, sagt es. »Wir reden nicht. Nicht, seit mein Vater und sie sich zerstritten. Eine lange, traurige Geschichte.« Und du hörst, wie lang sie ist.",
77: "Du beschließt, sie vor dem Morgen zusammenzubringen — Wren und die alte Nora, nach all den Jahren. Eine Kleinigkeit neben der Mauer und dem Hochwasser. Aber nicht nichts. Manche verschlossenen Türen lassen sich noch öffnen.",
78: "Die kleine Gestalt rührt sich nicht, und das Hochwasser kriecht auf sie zu, kalt und geduldig. Und doch kam jemand ganz hierher, ins Dunkel, allein. Du kannst sie nicht liegen lassen. Du musst näher und wissen, wer es ist.",
79: "Du gehst näher und erkennst sie sofort. Es ist Wren — das Enkelkind der alten Nora, seit Jahren nicht hier gesehen, seit dem Zerwürfnis der Familie. Dann kommt ein schwacher Laut aus dem Wasser, zu deinen Füßen. Jetzt machst du schnell.",
80: "Der Händler kommt ein letztes Mal, die Lampe schwingend. »Immer noch am Kämpfen?«, sagt er. »Lass den Fluss es holen. Letzte Chance, auf der Siegerseite zu stehen, Freund.« Dasselbe leichte Lächeln. Dieselbe alte Lüge.",
90: "Du bist zurück in der Gasse, durchnässt, das Schlimmste des Hochwassers lastet auf allem. An der Stufe liegt Nora grau und still. Entlang der Gasse ist die Mauer niedrig und beginnt zu lecken. Das ist die Stunde, in der sich alles entscheidet.",
91: "Du erreichst die Mauer: die Linie niedrig, das Ende leckt stark. Zu den Häusern am Ende hin ist der Fluss nahe daran, für immer überzutreten. Du musst die Mauer wieder fest und hoch bekommen — und zwar jetzt, schnell.",
92: "Dann erreicht dich endlich Hilfe — mehr Hände, mehr Säcke, feste Leute, die die Arbeit kennen. Du bist nicht mehr allein damit; andere teilen die Last. Es ist, als setzte man etwas Schweres ab, das man viel zu lange getragen hat.",
93: "Jetzt hältst du die Mauer — und was du tun kannst, hängt davon ab, was du mitgebracht hast. Mit echten Säcken hast du genug zum Arbeiten. Ohne sie musst du um jeden Zoll von Hand kämpfen. So oder so ist die Nacht lange nicht vorbei.",
94: "Du gehst hinunter, um nach Nora zu sehen, und ihre Augen öffnen sich ein wenig. Angst darin — dann, als sie dich sieht, ein wenig weniger. »Du hast sie gehalten«, flüstert sie. »Das hab ich«, sagst du leise. »Jetzt ruh dich aus.«",
95: "Die guten Säcke schaffen es. Du baust die Linie auf und stampfst sie fest, und entlang der Gasse steht die Mauer, fest und stark. Der Fluss wirft sich dagegen und wird gehalten. Das, denkst du, war der Sinn der ganzen Nacht.",
96: "Keine echten Säcke: du kämpfst um jeden Zoll von Hand. Du stopfst Schlamm und Sand in die Lücken, hältst die Linie mit deinem Körper, deinem Atem, deinem Willen. Vielleicht reicht es nicht. Aber du lässt sie nicht kampflos los.",
97: "Die Mauer ist niedrig und leckt, und du fürchtest, sie allein zu halten reicht nicht. Du hast alles getan mit dem, was du hattest. Aber sie hält vielleicht nicht. Du brauchst mehr — mehr Säcke, mehr Hände, oder beides.",
98: "Du blickst hinaus und siehst es. Weit am Rand des Wassers flammt ein Licht auf und fällt — wo niemand sein sollte, zeigt sich und verbirgt sich. Es zieht dein Auge. Und etwas Tieferes.",
99: "Das Licht am Rand des Wassers zeigt sich wieder — wo alle schwören, dass niemand wäre. Aber ein Licht bedeutet eine Hand, und eine Hand bedeutet einen Menschen. Einen Menschen, draußen, allein, in solch einem Hochwasser.",
100: "Dann kommt die lange Wache: du fütterst die Mauer, hältst Nora warm, wachst über das Wasser Stunde um Stunde. Nichts Aufregendes — nur stete, harte, sorgfältige Arbeit. Aber es ist die ganze Arbeit heute Nacht, und sie ist deine.",
101: "Und dann, endlich, wendet es sich. Der Fluss hört auf zu steigen. Er hält, fällt dann einen Zoll, dann noch einen. Der Himmel wird grau über den Dächern, und das erste dünne Licht kommt. Das Hochwasser verliert. Du hast die Nacht fast gehalten.",
102: "Das ist die härteste Stunde, kurz vor dem Umschwung. Der Fluss ist noch nicht gefallen; die Arme schmerzen, die Augen brennen. Aber du spürst die Nacht sich wenden, irgendwo darunter. Halte noch ein wenig durch.",
103: "Entlang der Gasse siehst du sie — Lampen, dunkle Gestalten, Sackwälle, die das Hochwasser halten. Andere Leute, draußen im Regen wie du. Auch die Straße kam durch diese Nacht. Du warst nie so allein, wie du dich fühltest.",
104: "Endlich kommt Hilfe die Gasse herauf — ein Lastwagen, mehr Hände, mehr Säcke, echte Hilfe in gutem Tempo. Du lehnst an der Mauer und siehst sie kommen, die Beine zittern. Aber das Schlimmste der Nacht liegt hinter dir.",
105: "Der Morgen steigt über die Straße, das Licht wird grau, dann blass und klar. Der Regen lässt endlich nach, und der Fluss sinkt das Ufer hinab. Die Häuser stehen noch, trocken drinnen. Das Schlimmste ist endlich vorbei.",
106: "Dann kommt er — der erste Vogel des Morgens, singend über den nassen Dächern, als hätte es kein Hochwasser gegeben. Nach der Nacht, die du hattest, wirkt es fast absurd. Und es ist schön, und du hältst inne, um zu lauschen.",
107: "Von der Gasse aus spähst du zum Rand des Wassers, wo ein Licht sich hebt, fällt und langsam wächst. Endlich kommt etwas, noch zu weit, um es zu erkennen. Aber ein Licht bedeutet jemanden — und jemand ist heute Nacht weit besser als niemand.",
110: "Das erste Licht kommt endlich, und die Nacht rechnet sich zusammen. Alles, was du draußen im Regen getan hast, kommt jetzt zu dir zurück — manches zum Stolzsein, manches nicht. Sehen wir also, worauf es alles hinauslief.",
111: "Die Nacht summiert sich — nicht mit einer großen Tat, sondern mit vielen kleinen. Was du gehalten, was du verweigert hast, für wen du in den Regen gingst. Alles zählt am Ende. Alles machte die Nacht zu dem, was sie war.",
112: "Es gibt mehr abzuwägen; die Nacht barg anderes. Ein Fremder, für den du anhieltest. Ein Mantel und eine Lampe, mit offener Hand verschenkt. Kleine Entscheidungen, im Regen getroffen, als es leichter gewesen wäre, vorbeizugehen.",
113: "Und was lässt dir die Nacht? Vielleicht keinen sauberen Sieg. Vielleicht nur dies: dass du hinausgingst, dass du es versuchtest. Als es dunkel, nass und leicht war, drinnen zu bleiben, tatst du es nicht. Das zählt.",
114: "Aber nicht jede Nacht endet gut. Manche Entscheidungen kosten mehr, als du wusstest; manche Türen lassen sich, einmal geöffnet, nicht mehr schließen. Das ist das harte Ende der Nacht — wo das Schlimmste zu dir zurückkommt.",
120: "Du hast die Mauer die ganze Nacht entlang der Gasse gehalten. Beim ersten Licht sinkt der Fluss, der Regen hört auf, und die Häuser — eine ganze Reihe Heime — bleiben trocken. Alles hielt, weil du im Regen bliebst und die Mauer nicht nachgeben ließt. Das ist alles, und es genügt.",
121: "Du hast dem Licht geantwortet, das niemand erklären konnte. Du fandest Wren, verloren und durchkältet am Rand des Wassers, und wärmtest es gerade rechtzeitig. Und mehr als ein Leben wurde gerettet. Wren ist Noras Enkelkind. Eine jahrelang verschlossene Tür öffnet sich wieder, im Grau des Morgens.",
122: "Es gab keine einzelne Heldentat — es gab etwas Besseres. Du machtest aus einer schlafenden Straße Menschen mit Säcken an jeder Tür, und zusammen brachten sie die Nacht durch. Niemand blieb darin allein. Das, am Ende, kann eine Straße sein.",
123: "Du hast den Betrug verweigert — sahst den Trick des Händlers und kehrtest ihm den Rücken. Du bewahrtest den Kopf und rettetest, was du konntest, mit anständigen Mitteln. Keine perfekte Nacht; du hast nicht alle gerettet. Aber sauber, und sauber genügt.",
124: "Du hast nicht die ganze Straße gerettet. Aber der Nachbar, für den du anhieltest, kommt jetzt zurück. Er hilft dir, die nahen Häuser zu retten und Nora zu wärmen. Nicht der volle Sieg. Aber eine Güte, so zeigt sich, kommt zurück.",
125: "Du hast deinen Mantel und deine Lampe an Ärmere gegeben und beendest die Nacht selbst durchkältet. Du hast nicht alles gerettet. Aber du bist nicht allein, und niemand, dem du begegnetest, ist es. Etwas in der Straße hat sich verschoben. Es ist ein Anfang, keine Rettung.",
126: "Du kommst knapp durch. Der Fluss wendet sich endlich, und ein dünner Morgen findet die meisten Häuser noch trocken. Kein Triumph, und niemand wird davon singen. Aber du kamst durch die Nacht — und das ist am Ende eine Erleichterung für sich.",
127: "Du hast nicht alles gerettet. Aber die Straße sah dich am Rand des Wassers, als andere im Bett blieben — sah dich es versuchen, in der schlimmsten Nacht des Jahres. Von heute an bist du jemand, den dieser Ort kennt. Und das ist nicht nichts.",
128: "Du nahmst den Handel des Händlers an, und am Morgen ist die Straße nicht mehr Noras zu retten. Der Fluss tat den Rest. Der Scheck in deiner Tasche ist kalt, und das Wasser an der Tür am Morgen auch. Du wirst nicht so bald vergessen, wie du ihn verdient hast.",
129: "Der Wehrsteg war eine Falle, genau wie Jack Reed gewarnt hatte. Du gingst im Dunkeln hinüber, und er nahm die ganze Nacht. Du schleppst dich heraus, durchnässt und zitternd, und erreichst die Häuser am Ende viel zu spät. Der Mühlbach kostete dich alles, was die Abkürzung versprach.",
130: "Du verbrachtest die Nacht mit den falschen Dingen, und die Mauer blieb zu lange niedrig. Beim Morgen ist der Fluss durch jede Tür, und die Straße ist ruiniert. Du gingst zwar in den Regen hinaus. Aber du hieltest die Mauer nicht, als es wirklich zählte.",
131: "Am Ende bliebst du drinnen, wo es warm und sicher war. Du sagtest dir, der Fluss sei zu hoch, es sei nicht deine Sache, Hilfe käme im Morgengrauen. Alles davon war wahr. Und die ganze Nacht, draußen, blieb die Mauer ungebaut. Dir ist nichts Schlimmes passiert. Du wirst lange, lange daran denken.",
}
def main():
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    data = json.load(open(OUT, encoding="utf-8")) if os.path.exists(OUT) else {}
    a = 0
    for nid, t in G.items():
        k = str(nid)
        if k not in data: a += 1
        data[k] = t
    data = {k: data[k] for k in sorted(data, key=lambda x: int(x))}
    json.dump(data, open(OUT, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    print("high-water/de.json: %d (+%d)" % (len(data), a))
if __name__ == "__main__":
    main()
